"""Export shifts for the printed rota."""

import logging

log = logging.getLogger(__name__)


def export_shifts(shifts, out):
    # FIXME: empty shifts print a blank page
    for shift in shifts:
        try:
            out.write(format_shift(shift))
        except Exception as exc:
            log.warning("could not export %s: %s", shift, exc)


def shift_label(shift):
    try:
        return shift["label"]
    except KeyError:
        pass
    return "Unnamed shift"


def parse_spots(text):
    try:
        return int(text)
    except ValueError as exc:
        raise ValueError(f"spots must be a whole number: {text!r}") from exc


def format_shift(shift):
    return f"{shift_label(shift)}: {shift.get('start', '?')}"

